import ("fmt";"net/http";"net/http/httptest";"encoding/json")
type Todo struct { ID int `json:"id"`; Title string `json:"title"`; Done bool `json:"done"` }
var todos=[]Todo{{ID:1,Title:"Learn Go",Done:false}}
